export async function getPublishedArticles(query?: string, topicSlug?: string) {
  let list = SEED_ARTICLES.filter((a) => a.status === 'PUBLISHED');

  if (topicSlug) {
    const topic = SEED_TOPICS.find((t) => t.slug === topicSlug);
    if (topic) {
      list = list.filter((a) => a.topic_id === topic.id);
    }
  }

  if (query && query.trim()) {
    list = list.filter(
      (a) => matchArabicQuery(a.title, query) || matchArabicQuery(a.excerpt, query)
    );
  }

  return list;
}

export async function getArticleBySlug(slug: string) {
  return SEED_ARTICLES.find((a) => a.slug === slug) || null;
}

export async function getTopicBySlug(slug: string) {
  return SEED_TOPICS.find((t) => t.slug === slug) || null;
}

export async function getAllTopics() {
  return SEED_TOPICS;
}

export async function getAuthor() {
  return SEED_AUTHOR;
}

export async function savePublishedArticle(articleData: Article & { revision: ArticleRevision }) {
  const index = SEED_ARTICLES.findIndex((a) => a.id === articleData.id || a.slug === articleData.slug);
  if (index >= 0) {
    SEED_ARTICLES[index] = articleData;
  } else {
    SEED_ARTICLES.unshift(articleData);
  }

  return articleData;
}
